      type: 'learning_lesson',
      handle: 'pre-snorkel-checklist-and-planning',
      lesson_id: 'R10',
      title: "Pre-Snorkel Checklist and Planning",
      short_description: "A practical before-you-go routine covering gear checks, sun and hair prep, condition checks, and when to cancel or postpone.",
      lesson_type: "Safety briefing",
